SELECT change_points
FROM points_flow
WHERE is_deleted = 0
  AND owner_id = #{ownerId}
  AND owner_type = #{ownerType}
  AND change_type != 'EXPIRED_DEDUCT'
  AND created_time BETWEEN #{startTime} AND #{endTime}

SELECT id,
change_points,
change_type,
batch_gain_date,
created_time,
remark

FROM points_flow


    is_deleted = 0
    AND owner_id = #{ownerId}
    AND owner_type = #{ownerType}


        AND ${dto.positiveValue ? 'change_points gt 0' : 'change_points lt 0'}



        AND change_type IN

            #{type}




        AND created_time >= #{dto.startTime}



        AND created_time <= #{dto.endTime}





        ORDER BY created_time


        ORDER BY created_time DESC
